enum WorkModule { sites, customers, orders, employees, time, calendar, reports, materials, machines, tasks }

class PincusWorkspace extends StatefulWidget {
  const PincusWorkspace({super.key});
  @override State<PincusWorkspace> createState() => _PincusWorkspaceState();
}

class _PincusWorkspaceState extends State<PincusWorkspace> {
  final db = AppDatabase();
  WorkModule module = WorkModule.sites;
  @override void dispose(){db.close();super.dispose();}
  @override Widget build(BuildContext context){
    final mobile=MediaQuery.sizeOf(context).width<800;
    return Scaffold(
      appBar: AppBar(backgroundColor:kGreen,foregroundColor:Colors.white,title:Row(children:[const Icon(Icons.park_outlined),const SizedBox(width:10),Text(title(module),style:const TextStyle(fontWeight:FontWeight.w700))]),actions:[IconButton(onPressed:(){},icon:const Icon(Icons.notifications_none)),const SizedBox(width:8)]),
      body:Row(children:[if(!mobile)WorkSidebar(selected:module,onSelect:(m)=>setState(()=>module=m)),Expanded(child:module==WorkModule.calendar?const CalendarView():module==WorkModule.sites?ModuleView(db:db,kind:module):ModuleView(db:db,kind:module))]),
      bottomNavigationBar:mobile?NavigationBar(selectedIndex:_mobileIndex(module),onDestinationSelected:(i)=>setState(()=>module=_mobileModule(i)),destinations:const [NavigationDestination(icon:Icon(Icons.dashboard_outlined),label:'Start'),NavigationDestination(icon:Icon(Icons.location_on_outlined),label:'Baustellen'),NavigationDestination(icon:Icon(Icons.people_outline),label:'Kunden'),NavigationDestination(icon:Icon(Icons.schedule_outlined),label:'Zeit'),NavigationDestination(icon:Icon(Icons.more_horiz),label:'Mehr')]):null,
    );
  }
  int _mobileIndex(WorkModule m)=>switch(m){WorkModule.sites=>1,WorkModule.customers=>2,WorkModule.time=>3,_=>0};
  WorkModule _mobileModule(int i)=>switch(i){1=>WorkModule.sites,2=>WorkModule.customers,3=>WorkModule.time,_=>WorkModule.sites};
}

class WorkSidebar extends StatelessWidget{
  final WorkModule selected;final ValueChanged<WorkModule> onSelect;
  const WorkSidebar({super.key,required this.selected,required this.onSelect});
  static const entries=<WorkModule>[WorkModule.sites,WorkModule.customers,WorkModule.orders,WorkModule.employees,WorkModule.time,WorkModule.calendar,WorkModule.reports,WorkModule.materials,WorkModule.machines,WorkModule.tasks];
  @override Widget build(BuildContext context)=>Container(width:112,color:Colors.white,child:Column(children:[Padding(padding:const EdgeInsets.all(9),child:Image.asset('assets/images/logo.png',height:54)),Expanded(child:ListView(children:entries.map((m)=>Padding(padding:const EdgeInsets.symmetric(horizontal:6,vertical:2),child:InkWell(borderRadius:BorderRadius.circular(14),onTap:()=>onSelect(m),child:Container(padding:const EdgeInsets.symmetric(vertical:8),decoration:BoxDecoration(color:selected==m?kPaleGreen:Colors.transparent,borderRadius:BorderRadius.circular(14)),child:Column(children:[Icon(icon(m),color:selected==m?kGreen:Colors.black54,size:27),const SizedBox(height:3),Text(title(m),textAlign:TextAlign.center,style:TextStyle(fontSize:12,fontWeight:selected==m?FontWeight.w700:FontWeight.w500,color:selected==m?kDarkGreen:Colors.black87))]))))).toList()))]));
