String title(WorkModule m)=>switch(m){WorkModule.sites=>'Baustellen',WorkModule.customers=>'Kunden',WorkModule.orders=>'Aufträge',WorkModule.employees=>'Mitarbeiter',WorkModule.time=>'Zeiterfassung',WorkModule.calendar=>'Kalender',WorkModule.reports=>'Berichte',WorkModule.materials=>'Material',WorkModule.machines=>'Maschinen',WorkModule.tasks=>'Aufgaben'};
