class ModuleView extends StatefulWidget{final AppDatabase db;final WorkModule kind;const ModuleView({super.key,required this.db,required this.kind});@override State<ModuleView> createState()=>_ModuleViewState();}
class _ModuleViewState extends State<ModuleView>{late Future<List<dynamic>> future;String search='';@override void initState(){super.initState();reload();}void reload()=>future=query();Future<List<dynamic>> query()async=>switch(widget.kind){WorkModule.sites:widget.db.select(widget.db.sites).get(),WorkModule.customers:widget.db.select(widget.db.customers).get(),WorkModule.orders:widget.db.select(widget.db.orders).get(),WorkModule.employees:widget.db.select(widget.db.employees).get(),WorkModule.time:widget.db.select(widget.db.timeEntries).get(),WorkModule.reports:widget.db.select(widget.db.reports).get(),WorkModule.materials:widget.db.select(widget.db.materialsTable).get(),WorkModule.machines:widget.db.select(widget.db.machinesTable).get(),WorkModule.tasks:widget.db.select(widget.db.tasksTable).get(),WorkModule.calendar:Future.value([])};
