Future<void> open([dynamic item])async{final v=await showDialog<Map<String,String>>(context:context,builder:(_)=>Editor(db:widget.db,kind:widget.kind,item:item));if(v==null)return;try{if(item==null)await insert(v);else await update(item,v);setState(reload);if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Eintrag gespeichert.'),backgroundColor:kGreen));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Fehler beim Speichern: $e'),backgroundColor:Colors.red));}}
Future<void> remove(dynamic x)async{final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('Eintrag löschen?'),content:Text('„${primary(x)}“ wird entfernt.'),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Abbrechen')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Löschen'))]));if(ok!=true)return;switch(widget.kind){case WorkModule.sites:await(widget.db.delete(widget.db.sites)..where((t)=>t.id.equals(x.id))).go();case WorkModule.customers:await(widget.db.delete(widget.db.customers)..where((t)=>t.id.equals(x.id))).go();case WorkModule.orders:await(widget.db.delete(widget.db.orders)..where((t)=>t.id.equals(x.id))).go();case WorkModule.employees:await(widget.db.delete(widget.db.employees)..where((t)=>t.id.equals(x.id))).go();case WorkModule.time:await(widget.db.delete(widget.db.timeEntries)..where((t)=>t.id.equals(x.id))).go();case WorkModule.reports:await(widget.db.delete(widget.db.reports)..where((t)=>t.id.equals(x.id))).go();case WorkModule.materials:await(widget.db.delete(widget.db.materialsTable)..where((t)=>t.id.equals(x.id))).go();case WorkModule.machines:await(widget.db.delete(widget.db.machinesTable)..where((t)=>t.id.equals(x.id))).go();case WorkModule.tasks:await(widget.db.delete(widget.db.tasksTable)..where((t)=>t.id.equals(x.id))).go();case WorkModule.calendar:break;}setState(reload);}
Future<void> insert(Map<String,String>v)async{switch(widget.kind){case WorkModule.sites:await widget.db.into(widget.db.sites).insert(SitesCompanion.insert(title:v['title']!,address:v['address']!,customerId:_st(v['customerId'])));case WorkModule.customers:await widget.db.into(widget.db.customers).insert(CustomersCompanion.insert(id:_id(),name:v['name']!,contact:Value(v['contact']??''),phone:Value(v['phone']??''),address:Value(v['address']??'')));case WorkModule.orders:await widget.db.into(widget.db.orders).insert(OrdersCompanion.insert(id:_id(),title:v['title']!,customerId:_st(v['customerId']),siteId:_it(v['siteId']),status:Value(v['status']??'Neu'),date:v['date']!,price:Value(_num(v['price']))));case WorkModule.employees:await widget.db.into(widget.db.employees).insert(EmployeesCompanion.insert(id:_id(),name:v['name']!,role:v['role']!,targetHours:Value(_num(v['targetHours']))));case WorkModule.time:await widget.db.into(widget.db.timeEntries).insert(TimeEntriesCompanion.insert(siteId:int.parse(v['siteId']!),employeeName:v['employeeName']!,date:_date(v['date']!),startTime:_dt(v['date']!,v['startTime']!),endTime:Value((v['endTime']??'').isEmpty?null:_dt(v['date']!,v['endTime']!)),breakMinutes:Value(_num(v['breakMinutes'])),notes:Value(_null(v['notes']))));case WorkModule.reports:await widget.db.into(widget.db.reports).insert(ReportsCompanion.insert(id:_id(),siteId:_it(v['siteId']),title:v['title']!,date:v['date']!,content:v['content']??''));case WorkModule.materials:await widget.db.into(widget.db.materialsTable).insert(MaterialsTableCompanion.insert(name:v['name']!,articleNumber:Value(_null(v['articleNumber'])),category:Value(_null(v['category'])),unit:Value(v['unit']??'Stk'),stock:Value(_num(v['stock'])),minimumStock:Value(_num(v['minimumStock'])),location:Value(_null(v['location'])),unitPrice:Value(_dbl(v['unitPrice'])),notes:Value(_null(v['notes']))));case WorkModule.machines:await widget.db.into(widget.db.machinesTable).insert(MachinesTableCompanion.insert(name:v['name']!,serialNumber:Value(_null(v['serialNumber'])),operatingHours:Value(_num(v['operatingHours'])),status:Value(v['status']??'bereit'),notes:Value(_null(v['notes']))));case WorkModule.tasks:await widget.db.into(widget.db.tasksTable).insert(TasksTableCompanion.insert(title:v['title']!,description:Value(_null(v['description'])),siteId:_it(v['siteId']),category:v['category']!,priority:Value(v['priority']??'normal'),status:Value(v['status']??'offen'),dueDate:Value((v['dueDate']??'').isEmpty?null:_date(v['dueDate']!)));case WorkModule.calendar:break;}}
